import re

def parse_expressions(code):
    """Kodu yorum satırlarıyla temizle ve ifadelere ayır."""
    # Yorumları kaldır
    lines = code.split('\n')
    cleaned_lines = []
    for line in lines:
        if '#' in line:
            line = line[:line.index('#')]
        cleaned_lines.append(line)

    combined = '\n'.join(cleaned_lines)

    # Satır sonu ve ; ile ayır, boş ifadeleri ekleme
    # Önce ; ile parçala, sonra her parçayı satır sonu ile parçala
    parts = re.split(r'[;]', combined)
    expressions = []
    for part in parts:
        # Her parçayı satır sonu ile parçala
        for line in part.split('\n'):
            line = line.strip()
            if line:
                expressions.append(line)

    return expressions


def tokenize(expr):
    """İfadenin tokenlarını döndür: sayı, isim, işleç, parantez."""
    tokens = []
    i = 0
    n = len(expr)

    while i < n:
        ch = expr[i]

        # Boşlukları atla
        if ch.isspace():
            i += 1
            continue

        # Sayı
        if ch.isdigit() or (ch == '.' and i+1 < n and expr[i+1].isdigit()):
            j = i
            if ch == '.':
                j += 1
            while j < n and (expr[j].isdigit() or expr[j] == '.'):
                j += 1
            num_str = expr[i:j]
            # .3 veya 3. formatında mı kontrol et
            if num_str.startswith('.') or num_str.endswith('.'):
                pass  # Geçersiz ama önce devam et
            if '.' in num_str:
                try:
                    tokens.append(('FLOAT', float(num_str)))
                except:
                    tokens.append(('NAME', num_str))  # Hata, isim olarak
            else:
                tokens.append(('INT', int(num_str)))
            i = j
            continue

        # İsim (değişken)
        if ch.isalpha() or ch == '_':
            j = i
            while j < n and (expr[j].isalnum() or expr[j] == '_'):
                j += 1
            name = expr[i:j]
            tokens.append(('NAME', name))
            i = j
            continue

        # Operatörler: + - * / % **
        if ch in '+-*/%':
            tokens.append(('OP', ch))
            i += 1
            continue

        # Üs operatörü **
        if ch == '*' and i+1 < n and expr[i+1] == '*':
            tokens.append(('OP', '**'))
            i += 2
            continue

        # Parantez
        if ch == '(' or ch == ')':
            tokens.append(('LPAREN', ch) if ch == '(' else ('RPAREN', ch))
            i += 1
            continue

        # Hatalı karakter
        raise SyntaxError(f"Söz dizimi hatası: '{ch}'")

    return tokens


